  \clef "treble" \numericTimeSignature \time 4/4 \key c \major \oneVoice \U g4
  \voiceOne \U a4 \U b4 \U ais4 ~ | % 1
  \oneVoice bes4 r4 r8 e,8 ~ [ g8 ~ c8 ~ ] | % 2
  <e, g c>2 r2 | % 3
  r4 g'8 \laissezVibrer r8 r2 \bar "|."
}

PartPOneVoiceTwo = \relative g' {
  \clef "treble" \numericTimeSignature \time 4/4 \key c \major s4 \D g8 [ \D fis8
  ] \D g4 \D cis,8 e8\rest s1*3 \bar "|."
}


